ner's decision, 2026-10-12). What is retained, where, for how long and how it is disposed of are unchanged."$a4$::jsonb;
begin
  select count(*) into n from public.sop_documents where sop_number = 'FSQM-014' and status = 'active';
  if n <> 1 then raise exception 'FSQM-014: expected one active document, found %', n; end if;
  select * into d from public.sop_documents where sop_number = 'FSQM-014' and status = 'active';
  if d.revision = 'v2' and d.content->'responsibility' = resp_new and d.content->'revision_history' = h_new then
    raise notice 'FSQM-014: already at v2 as intended, left alone';
    return;
  end if;
  if d.revision <> 'New' or d.content->'responsibility' is distinct from resp_old or d.content->'revision_history' is distinct from h_old then
    raise exception 'FSQM-014 is not the document this migration was written against';
  end if;
  update public.sop_documents
     set content = jsonb_set(jsonb_set(content, '{responsibility}', resp_new), '{revision_history}', h_new),
         revision = 'v2', effective_date = '2026-10-12', approved_by = 'GJM'
   where id = d.id;
end $$;
